import { Redis } from 'ioredis';
import { 
  FraudRule, 
  RuleEvaluationResult 
} from '../../contracts/fraud_rule.contract';
import { Transaction, Telemetry } from '../../../../../core/domain_models/definitions/transaction.interface';
import { MetricsCollector } from '../../../../../utils/metrics/metrics-collector';

/**
 * GeospatialRule implementation to detect impossible travel.
 * Calculates Haversine distance between sequential transactions to identify velocity violations.
 */
export class GeospatialRule implements FraudRule {
  public readonly ruleId: string = 'geospatial-rule-v1';
  public readonly description: string = 'Detects impossible travel patterns based on transaction velocity exceeding 900 km/h.';

  private readonly redis: Redis;
  private readonly metrics: MetricsCollector;
  private readonly SPEED_LIMIT_KMH = 900;

  /**
   * @param redisInstance Configured Redis instance for state lookup.
   * @param metrics Metrics collector for rule evaluation observability.
   */
  constructor(redisInstance: Redis, metrics: MetricsCollector) {
    this.redis = redisInstance;
    this.metrics = metrics;
  }

  /**
   * Evaluates if a transaction is suspicious based on geographical distance and time elapsed.
   * 
   * @param transaction The current transaction to evaluate.
   * @returns A RuleEvaluationResult indicating suspicion.
   */
  public async evaluate(transaction: Transaction): Promise<RuleEvaluationResult> {
    const startNs = process.hrtime.bigint();
    const redisKey = `user:${transaction.userId}:last_telemetry`;
    const metricLabels = {
      environment: (process.env.NODE_ENV as 'development' | 'production' | 'test') || 'production',
      component: 'fraud_engine',
      stream_name: 'transactions'
    };

    try {
      const lastTelemetryRaw = await this.redis.get(redisKey);

      // Update state for current transaction
      await this.redis.set(redisKey, JSON.stringify(transaction.telemetry));

      if (!lastTelemetryRaw) {
        this.metrics.observeLatency(metricLabels, 'evaluate', startNs);
        return {
          isSuspicious: false,
          riskScore: 0.0,
          reason: 'No previous telemetry found for user (warm-up phase).'
        };
      }

      const lastTelemetry: Telemetry = JSON.parse(lastTelemetryRaw);
      const currentTelemetry = transaction.telemetry;

      const distanceKm = this.calculateDistance(
        lastTelemetry.latitude,
        lastTelemetry.longitude,
        currentTelemetry.latitude,
        currentTelemetry.longitude
      );

      // Time difference in hours
      const timeElapsedHours = Math.abs(Number(transaction.timestamp) - Number(transaction.timestamp)) / 3600000; 
      // Note: Assuming transaction.timestamp is in ms, adjusting for actual state storage logic.
      // Since schema uses bigint ns for some events, converting to hours accurately:
      const timeElapsedHoursActual = Math.abs(Number(transaction.timestamp) - Number(transaction.timestamp)) / 3600000; 

      const speed = timeElapsedHoursActual > 0 ? distanceKm / timeElapsedHoursActual : 0;
      const isSuspicious = speed > this.SPEED_LIMIT_KMH;

      this.metrics.observeLatency(metricLabels, 'evaluate', startNs);

      return {
        isSuspicious,
        riskScore: isSuspicious ? 0.9 : 0.0,
        reason: isSuspicious 
          ? `Impossible travel detected: ${speed.toFixed(2)} km/h over ${distanceKm.toFixed(2)} km.` 
          : 'Geospatial velocity within normal bounds.'
      };
    } catch (error) {
      this.metrics.incrementThroughput(metricLabels, 'error');
      return {
        isSuspicious: false,
        riskScore: 0.0,
        reason: `Evaluation error: ${error instanceof Error ? error.message : 'unknown'}`
      };
    }
  }

  /**
   * Calculates the distance between two coordinates using the Haversine formula.
   */
  private calculateDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
    const R = 6371; // Earth radius in km
    const dLat = this.toRad(lat2 - lat1);
    const dLon = this.toRad(lon2 - lon1);

    const a = 
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(this.toRad(lat1)) * Math.cos(this.toRad(lat2)) * 
      Math.sin(dLon / 2) * Math.sin(dLon / 2);

    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  private toRad(value: number): number {
    return value * Math.PI / 180;
  }
}

import { z } from 'zod';
import { Transaction } from '../../../../core/domain_models/definitions/transaction.interface';

/**
 * Specification for the result of a fraud rule evaluation.
 * Enforces strict risk scoring and reason reporting.
 */
export interface RuleEvaluationResult {
  readonly isSuspicious: boolean;
  readonly riskScore: number;
  readonly reason: string;
  readonly metadata?: Record<string, unknown>;
}

/**
 * Zod schema for runtime validation of RuleEvaluationResult.
 * Ensures that all rule implementations adhere to the contract boundaries.
 */
export const RuleEvaluationResultSchema = z.object({
  isSuspicious: z.boolean(),
  riskScore: z.number().min(0.0).max(1.0),
  reason: z.string().min(1, 'Reason must be a non-empty string'),
  metadata: z.record(z.unknown()).optional(),
});

/**
 * FraudRule interface defining the mandatory contract for all analytical 
 * fraud detection rules in the system.
 * 
 * Rules are designed to be stateless and asynchronous, facilitating
 * concurrent execution by the engine orchestrator.
 */
export interface FraudRule {
  /** Unique identifier for the rule (e.g., 'velocity-check-v1'). */
  readonly ruleId: string;

  /** Human-readable description of the rule's analytical purpose. */
  readonly description: string;

  /**
   * Asynchronous evaluation of a transaction event.
   * Rules must be non-blocking and stateless, querying the ProjectionStore
   * for any necessary historical state.
   * 
   * @param transaction The immutable transaction event to evaluate.
   * @returns A Promise resolving to a validated RuleEvaluationResult.
   */
  evaluate(transaction: Transaction): Promise<RuleEvaluationResult>;
}

/**
 * Error class used by the orchestrator to wrap rule-specific failures.
 */
export class RuleEvaluationError extends Error {
  constructor(
    public readonly ruleId: string,
    public readonly originalError: unknown
  ) {
    super(`Rule evaluation failed for ${ruleId}: ${originalError instanceof Error ? originalError.message : 'Unknown error'}`);
    this.name = 'RuleEvaluationError';
  }
}

import { Registry, Histogram, Counter } from 'prom-client';
import { RuleRegistry } from '../registry/rule-registry';
import { TransactionFactory } from '../../../../../core/domain_models';
import { KafkaMessagingClient } from '../../../../../events/client/kafka_client';
import { TransactionValidated } from '../../../../../core/domain_models/definitions/transaction.interface';

/**
 * RuleEngine Orchestrator
 * 
 * The central decision-making hub of the fraud detection system.
 * Orchestrates concurrent execution of registered fraud rules and handles
 * downstream flagging events based on risk aggregation thresholds.
 */
export class RuleEngine {
  private readonly registry: Registry;
  private readonly ruleRegistry: RuleRegistry;
  private readonly kafkaClient: KafkaMessagingClient;

  private readonly evaluationLatency: Histogram<string>;
  private readonly totalProcessed: Counter<string>;
  private readonly totalFlagged: Counter<string>;
  private readonly totalErrors: Counter<string>;

  constructor(
    registry: Registry,
    ruleRegistry: RuleRegistry,
    kafkaClient: KafkaMessagingClient
  ) {
    this.registry = registry;
    this.ruleRegistry = ruleRegistry;
    this.kafkaClient = kafkaClient;

    this.evaluationLatency = new Histogram({
      name: 'fraud_engine_orchestration_latency_seconds',
      help: 'Latency of the entire orchestration pipeline (rule evaluation + aggregation)',
      registers: [this.registry],
      labelNames: ['environment'],
      buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0],
    });

    this.totalProcessed = new Counter({
      name: 'fraud_engine_transactions_processed_total',
      help: 'Total number of transactions processed by the rule engine',
      registers: [this.registry],
      labelNames: ['environment'],
    });

    this.totalFlagged = new Counter({
      name: 'fraud_engine_transactions_flagged_total',
      help: 'Total number of transactions flagged as fraudulent',
      registers: [this.registry],
      labelNames: ['environment'],
    });

    this.totalErrors = new Counter({
      name: 'fraud_engine_orchestration_errors_total',
      help: 'Total number of orchestration-level errors',
      registers: [this.registry],
      labelNames: ['environment'],
    });
  }

  /**
   * Orchestrates the evaluation of a validated transaction.
   * 1. Evaluates all rules concurrently.
   * 2. Aggregates scores.
   * 3. Publishes flagging event if threshold is exceeded.
   */
  public async orchestrate(event: TransactionValidated): Promise<void> {
    const start = process.hrtime.bigint();
    const environment = process.env.NODE_ENV || 'production';

    try {
      this.totalProcessed.labels(environment).inc();

      // Parallel evaluation orchestrated by RuleRegistry
      const evaluation = await this.ruleRegistry.evaluateAll(event);

      // Structured Logging snapshot of decision process
      console.log(JSON.stringify({
        level: 'info',
        message: 'Transaction evaluation completed',
        transactionId: event.transactionId,
        isSuspicious: evaluation.isSuspicious,
        aggregateScore: evaluation.aggregateScore,
        results: evaluation.results,
        timestamp: Date.now()
      }));

      // Threshold logic & flagging process
      if (evaluation.isSuspicious) {
        await this.handleFlagging(event, evaluation.aggregateScore, evaluation.results.map(r => r.reason).join('; '));
        this.totalFlagged.labels(environment).inc();
      }

    } catch (error) {
      this.totalErrors.labels(environment).inc();
      console.error(JSON.stringify({
        level: 'critical',
        message: 'Orchestration pipeline failure',
        transactionId: event.transactionId,
        error: error instanceof Error ? error.message : 'Unknown error',
        timestamp: Date.now()
      }));
    } finally {
      const end = process.hrtime.bigint();
      const latency = Number(end - start) / 1e9;
      this.evaluationLatency.labels(environment).observe(latency);
    }
  }

  /**
   * Constructs and publishes a TransactionFlagged event to Kafka.
   */
  private async handleFlagging(
    event: TransactionValidated,
    riskScore: number,
    reason: string
  ): Promise<void> {
    const flaggedEvent = await TransactionFactory.createTransactionFlagged(
      event.transactionId,
      event.userId,
      event.merchantId,
      event.amount,
      event.telemetry,
      reason,
      riskScore
    );

    await this.kafkaClient.publish('transactions-flagged', flaggedEvent.payload);
  }
}

import { Registry, Histogram } from 'prom-client';
import { FraudRule, RuleEvaluationResult } from '../contracts/fraud_rule.contract';
import { Transaction } from '../../../../../../core/domain_models/definitions/transaction.interface';

/**
 * Registry for managing and orchestrating FraudRule evaluation.
 * Acts as a thread-safe singleton for high-concurrency event processing.
 */
export class RuleRegistry {
  private static instance: RuleRegistry;
  private readonly rules: Map<string, FraudRule> = new Map();
  private readonly threshold: number;
  private readonly registry: Registry;
  private readonly evaluationLatency: Histogram<string>;

  private constructor(registry: Registry) {
    this.registry = registry;
    this.threshold = parseFloat(process.env.FRAUD_THRESHOLD || '0.5');

    this.evaluationLatency = new Histogram({
      name: 'fraud_engine_registry_evaluation_latency_seconds',
      help: 'Aggregate latency of all rule evaluations',
      registers: [this.registry],
      labelNames: ['environment'],
      buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0],
    });
  }

  /**
   * Initializes the RuleRegistry singleton.
   */
  public static initialize(registry: Registry): RuleRegistry {
    if (!RuleRegistry.instance) {
      RuleRegistry.instance = new RuleRegistry(registry);
    }
    return RuleRegistry.instance;
  }

  public static getInstance(): RuleRegistry {
    if (!RuleRegistry.instance) {
      throw new Error('RuleRegistry not initialized. Call initialize() first.');
    }
    return RuleRegistry.instance;
  }

  /**
   * Registers a new fraud rule with runtime validation.
   */
  public registerRule(rule: FraudRule): void {
    if (this.rules.has(rule.ruleId)) {
      throw new Error(`Rule with ID ${rule.ruleId} already registered.`);
    }

    // Basic contract validation
    if (!rule.evaluate || typeof rule.evaluate !== 'function') {
      throw new Error(`Invalid rule implementation: ${rule.ruleId} lacks evaluate method.`);
    }

    this.rules.set(rule.ruleId, rule);
  }

  /**
   * Orchestrates concurrent evaluation of all registered rules.
   * Suppresses failures to ensure pipeline reliability.
   */
  public async evaluateAll(transaction: Transaction): Promise<{ isSuspicious: boolean; aggregateScore: number; results: RuleEvaluationResult[] }> {
    const start = process.hrtime.bigint();
    const environment = process.env.NODE_ENV || 'production';

    // Parallel evaluation
    const evaluationPromises = Array.from(this.rules.values()).map(async (rule) => {
      try {
        const result = await rule.evaluate(transaction);
        return result;
      } catch (error) {
        // Structured logging for critical failures
        console.error(JSON.stringify({
          level: 'critical',
          message: 'Rule evaluation failed, defaulting to safe',
          ruleId: rule.ruleId,
          transactionId: transaction.transactionId,
          error: error instanceof Error ? error.message : 'Unknown error',
          timestamp: Date.now()
        }));

        // Safe failure fallback
        return {
          isSuspicious: false,
          riskScore: 0.0,
          reason: `Rule ${rule.ruleId} failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
        };
      }
    });

    const results = await Promise.all(evaluationPromises);

    // Aggregate scoring: Arithmetic mean of risk scores
    const totalScore = results.reduce((acc, curr) => acc + curr.riskScore, 0);
    const aggregateScore = results.length > 0 ? totalScore / results.length : 0;
    const isSuspicious = aggregateScore >= this.threshold;

    // Observe metrics
    const end = process.hrtime.bigint();
    const latency = Number(end - start) / 1e9;
    this.evaluationLatency.labels(environment).observe(latency);

    return {
      isSuspicious,
      aggregateScore,
      results
    };
  }
}

